import 'package:flutter/material.dart';
import '../../services/api_service.dart';
import '../../widgets/app_button.dart';
class CreatePostScreen extends StatefulWidget { final VoidCallback? onCreated; const CreatePostScreen({super.key, this.onCreated}); @override State<CreatePostScreen> createState() => _CreatePostScreenState(); }
class _CreatePostScreenState extends State<CreatePostScreen> {
 final _controller = TextEditingController(); bool _loading = false;
 @override void dispose() { _controller.dispose(); super.dispose(); }
 Future<void> _submit() async { final content = _controller.text.trim(); if (content.isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Write something before posting.'))); return; } setState(() => _loading = true); try { await ApiService.instance.createPost(content); if (!mounted) return; ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Post published!'))); widget.onCreated?.call(); if (widget.onCreated == null) Navigator.pop(context, true); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e'))); } finally { if (mounted) setState(() => _loading = false); } }
 @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Create post'), leading: widget.onCreated == null ? null : IconButton(icon: const Icon(Icons.close), onPressed: widget.onCreated)), body: SafeArea(child: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Share a thought', style: TextStyle(fontSize: 25, fontWeight: FontWeight.w800)), const SizedBox(height: 8), Text('Your community is listening.', style: TextStyle(color: Theme.of(context).hintColor)), const SizedBox(height: 22), Expanded(child: TextField(controller: _controller, autofocus: true, maxLines: null, expands: true, textAlignVertical: TextAlignVertical.top, maxLength: 5000, decoration: const InputDecoration(hintText: 'What would you like to share?', alignLabelWithHint: true))), const SizedBox(height: 14), AppButton(label: 'Publish post', icon: Icons.send_rounded, loading: _loading, onPressed: _submit)]))));
}
